import { useState } from "react";

import Calendar from "./components/Calendar";

function App() {

    const [events, setEvents] = useState([
        {
            id: 1,
            title: "Design Review",
            date: "Monday",
            time: "10:00"
        },
        {
            id: 2,
            title: "Team Meeting",
            date: "Tuesday",
            time: "11:00"
        },
        {
            id: 3,
            title: "Write Proposal",
            date: "Wednesday",
            time: "13:00"
        },
        {
            id: 4,
            title: "Client Demo",
            date: "Thursday",
            time: "15:00"
        },
        {
            id: 5,
            title: "Portfolio Review",
            date: "Thursday",
            time: "18:00"
        },
        {
            id: 6,
            title: "Grocery Run",
            date: "Saturday",
            time: "10:00"
        },
        {
            id: 7,
            title: "Sprint Planning",
            date: "Sunday",
            time: "11:00"
        }
    ]);

    return (

        <div>

            <h1>📅 Social Post Scheduler</h1>

            <p>
                Schedule and manage your posts
            </p>

  <Calendar
    events={events}
    setEvents={setEvents}
/>

        </div>

    );
}

export default App;
